-- Seed idempotente da biblioteca de perguntas das seis anamneses.

on conflict (id) do update set code=excluded.code,clinical_concept_id=excluded.clinical_concept_id,label=excluded.label,help_text=excluded.help_text,field_type=excluded.field_type,options=excluded.options,validation=excluded.validation,active=excluded.active;

on conflict (id) do update set anamnesis_type_id=excluded.anamnesis_type_id,question_definition_id=excluded.question_definition_id,section=excluded.section,position=excluded.position,required=excluded.required,conditional_rule=excluded.conditional_rule,active=excluded.active;
